NP_functionality.VERILOG_PROVIDED:
reg waiting_state;
wire waiting_state_next;
reg flush_reg;
reg done_reg;
wire done_reg_next;
reg M_DataRdy_reg_old;
wire M_DataRdy_reg;
reg M_back_pressure_reg_old;
reg [BITSIZE_M_Rdata_ram -1 : 0] M_Rdata_ram_reg_old;
wire [BITSIZE_M_Rdata_ram -1 : 0] M_Rdata_ram_reg;
reg [BITSIZE_Mout_addr_ram -1 : 0] Mout_addr_ram_reg_old;
wire [BITSIZE_Mout_addr_ram -1 : 0] Mout_addr_ram_reg;
reg [BITSIZE_Mout_Wdata_ram -1 : 0] Mout_Wdata_ram_reg_old;
wire [BITSIZE_Mout_Wdata_ram -1 : 0] Mout_Wdata_ram_reg;
reg [BITSIZE_Mout_data_ram_size -1 : 0] Mout_data_ram_size_reg_old;
wire [BITSIZE_Mout_data_ram_size -1 : 0] Mout_data_ram_size_reg;
reg [BITSIZE_Mout_tag -1 :0] Mout_tag_reg;
wire [BITSIZE_Mout_tag -1 :0] Mout_tag_reg_next;

always @(posedge clock) 
begin
  if(1RESET_VALUE)
  begin
    waiting_state <= 0;
    flush_reg <= 0;
    done_reg <= 0;
    Mout_tag_reg <= 0;
    Mout_addr_ram_reg_old <= 0;
    Mout_Wdata_ram_reg_old <= 0;
    Mout_data_ram_size_reg_old <= 0;
    M_DataRdy_reg_old <= 0;
    M_Rdata_ram_reg_old <= 0;
    M_back_pressure_reg_old <= 0;
  end
  else
  begin
    waiting_state <= waiting_state_next;
    flush_reg <= dirty;
    done_reg <= done_reg_next;
    Mout_tag_reg <= Mout_tag_reg_next;
    Mout_addr_ram_reg_old <= Mout_addr_ram_reg;
    Mout_Wdata_ram_reg_old <= Mout_Wdata_ram_reg;
    Mout_data_ram_size_reg_old <= Mout_data_ram_size_reg;
    M_DataRdy_reg_old <= M_DataRdy_reg;
    M_Rdata_ram_reg_old <= M_Rdata_ram_reg;
    M_back_pressure_reg_old <= M_back_pressure;
  end 
end

assign flush = flush_reg && done_reg;
assign done = done_reg && !dirty;
assign done_reg_next = done_input || (done_reg && dirty);
assign waiting_state_next = (waiting_state && !ready) || (!waiting_state && (Mout_oe_ram || Mout_we_ram) && !M_back_pressure);

assign M_tag = Mout_tag_reg;
assign M_Rdata_ram = M_DataRdy_reg ? M_Rdata_ram_reg : {BITSIZE_M_Rdata_ram{1'b0}};
assign M_DataRdy = M_DataRdy_reg;

assign Mout_tag_reg_next = (M_back_pressure || (waiting_state && !ready)) ? Mout_tag_reg : Mout_tag;
assign M_DataRdy_reg = M_back_pressure_reg_old ? M_DataRdy_reg_old : ready;
assign M_Rdata_ram_reg = M_back_pressure_reg_old ? M_Rdata_ram_reg_old : rdata;

assign Mout_addr_ram_reg = (waiting_state && !ready) ? Mout_addr_ram_reg_old : Mout_addr_ram;
assign Mout_Wdata_ram_reg = (waiting_state && !ready) ? Mout_Wdata_ram_reg_old : Mout_Wdata_ram;
assign Mout_data_ram_size_reg = (waiting_state && !ready) ? Mout_data_ram_size_reg_old :  Mout_data_ram_size;

assign addr = Mout_addr_ram_reg[BITSIZE_Mout_addr_ram - 1:$clog2(BITSIZE_Mout_Wdata_ram / 8)];
assign wdata = Mout_Wdata_ram_reg;
assign valid = (Mout_oe_ram || Mout_we_ram) && !M_back_pressure && (!waiting_state || (waiting_state && ready));
assign wstrb = {BITSIZE_wstrb{Mout_we_ram}} & ((1 << (Mout_data_ram_size_reg >> 3)) - 1);
assign Mout_back_pressure = M_back_pressure | ((Mout_oe_ram || Mout_we_ram) && waiting_state);

assign m_axi_arlen = 0;
assign m_axi_arburst = BURST_TYPE;
assign m_axi_arlock = 0;
assign m_axi_arcache = 0;
assign m_axi_arprot = 0;
assign m_axi_arqos = 0;
assign m_axi_awlen = 0;
assign m_axi_awburst = BURST_TYPE;
assign m_axi_awlock = 0;
assign m_axi_awcache = 0;
assign m_axi_awprot = 0;
assign m_axi_awqos = 0;
assign m_axi_wlast = 1;

`ifndef _SIM_HAVE_CLOG2
  function integer log2;
     input integer value;
     integer temp_value;
    begin
      temp_value = value-1;
      for (log2=0; temp_value>0; log2=log2+1)
        temp_value = temp_value>>1;
    end
  endfunction
`endif

wire [2:0] size_next;

generate
  `ifdef _SIM_HAVE_CLOG2
    assign size_next = $clog2(Mout_data_ram_size >> 3);
  `else
    assign size_next = `log2(Mout_data_ram_size >> 3);
  `endif
endgenerate

reg Mout_back_pressure_reg;
reg double_answer_first;
wire double_answer_first_next;
reg double_answer_second;
wire double_answer_second_next;

reg m_axi_awvalid_reg, m_axi_awvalid_next;
reg m_axi_wvalid_reg, m_axi_wvalid_next;
reg m_axi_arvalid_reg, m_axi_arvalid_next;

always @(*)
begin
  Mout_back_pressure_reg = 0;
  if(m_axi_awvalid_reg && !m_axi_awready)
  begin
    Mout_back_pressure_reg = 1;
  end
  else if(m_axi_wvalid_reg && !m_axi_wready)
  begin
    Mout_back_pressure_reg = 1;
  end
  else if(m_axi_arvalid_reg && !m_axi_arready)
  begin
    Mout_back_pressure_reg = 1;
  end
end

assign Mout_back_pressure = Mout_back_pressure_reg;

reg M_back_pressure_old;
reg [BITSIZE_M_tag-1:0] m_axi_bid_reg;
wire [BITSIZE_M_tag-1:0] m_axi_bid_reg_next;
reg [BITSIZE_M_tag-1:0] m_axi_rid_reg;
wire [BITSIZE_M_tag-1:0] m_axi_rid_reg_next;

always @(posedge clock 1RESET_EDGE)
begin
  if(1RESET_VALUE)
  begin
    M_back_pressure_old <= 0;
  end
  else
  begin
    M_back_pressure_old <= M_back_pressure;
  end
end

always @(posedge clock 1RESET_EDGE)
begin
  if(1RESET_VALUE)
  begin
    m_axi_bid_reg <= 0;
    m_axi_rid_reg <= 0;
  end
  else
  begin
    m_axi_bid_reg <= m_axi_bid_reg_next;
    m_axi_rid_reg <= m_axi_rid_reg_next;
  end
end

assign m_axi_bid_reg_next = (m_axi_bvalid && m_axi_bready) ? m_axi_bid : m_axi_bid_reg;
assign m_axi_rid_reg_next = (m_axi_rvalid && m_axi_rready) ? m_axi_rid : m_axi_rid_reg;

always @(posedge clock 1RESET_EDGE)
begin
  if(1RESET_VALUE)
  begin
    m_axi_awvalid_reg <= 0;
    m_axi_wvalid_reg <= 0;
  end
  else 
  begin
    m_axi_awvalid_reg <= m_axi_awvalid_next;
    m_axi_wvalid_reg <= m_axi_wvalid_next;
  end 
end

always @(*)
begin
  m_axi_awvalid_next = m_axi_awvalid_reg;
  m_axi_wvalid_next = m_axi_wvalid_reg;
  if(Mout_we_ram && !Mout_back_pressure_reg)
  begin
    m_axi_awvalid_next = 1;
    m_axi_wvalid_next = 1;
  end
  else
  begin
    if(m_axi_awready)
    begin
      m_axi_awvalid_next = 0;  
    end
    if(m_axi_wready)
    begin
      m_axi_wvalid_next = 0;  
    end
  end
end

assign m_axi_wvalid = m_axi_wvalid_reg;
assign m_axi_awvalid = m_axi_awvalid_reg;

reg [BITSIZE_Mout_Wdata_ram-1:0] m_axi_wdata_reg, m_axi_wdata_next;
reg [BITSIZE_m_axi_wstrb-1:0] m_axi_wstrb_reg, m_axi_wstrb_next;

always @(posedge clock 1RESET_EDGE)
begin
  if(1RESET_VALUE)
  begin
    m_axi_wdata_reg <= 0;
    m_axi_wstrb_reg <= 0;
  end
  else
  begin
    m_axi_wdata_reg <= m_axi_wdata_next;
    m_axi_wstrb_reg <= m_axi_wstrb_next;
  end
end

always @(*)
begin
  m_axi_wdata_next = m_axi_wdata_reg;
  m_axi_wstrb_next = m_axi_wstrb_reg;
  if(Mout_we_ram && (!m_axi_wvalid_reg || m_axi_wready))
  begin
    m_axi_wdata_next = Mout_Wdata_ram;
    m_axi_wstrb_next = ((1 << (Mout_data_ram_size >> 3)) - 1);
  end
end

assign m_axi_wdata = m_axi_wdata_reg; 
assign m_axi_wstrb = m_axi_wstrb_reg;

reg [BITSIZE_m_axi_awaddr-1:0] m_axi_awaddr_reg, m_axi_awaddr_next;
reg [BITSIZE_m_axi_awsize-1:0] m_axi_awsize_reg, m_axi_awsize_next;
reg [BITSIZE_m_axi_awid-1:0] m_axi_awid_reg, m_axi_awid_next;


always @(posedge clock 1RESET_EDGE)
begin
  if(1RESET_VALUE)
  begin
    m_axi_awaddr_reg <= 0;
    m_axi_awid_reg <= 0;
    m_axi_awsize_reg <= 0;
  end
  else
  begin
    m_axi_awaddr_reg <= m_axi_awaddr_next;
    m_axi_awid_reg <= m_axi_awid_next;
    m_axi_awsize_reg <= m_axi_awsize_next;
  end
end

always @(*)
begin
  if(Mout_we_ram && (!m_axi_awvalid_reg || m_axi_awready))
  begin
    m_axi_awaddr_next = Mout_addr_ram;
    m_axi_awid_next = Mout_tag;
    m_axi_awsize_next = size_next;
  end
  else
  begin
    m_axi_awaddr_next = m_axi_awaddr_reg;
    m_axi_awid_next = m_axi_awid_reg;
    m_axi_awsize_next = m_axi_awsize_reg;
  end
end

assign m_axi_awaddr = m_axi_awaddr_reg;
assign m_axi_awid = m_axi_awid_reg;
assign m_axi_awsize = m_axi_awsize_reg;

always @(posedge clock 1RESET_EDGE)
begin
  if(1RESET_VALUE)
  begin
    m_axi_arvalid_reg <= 0;
  end
  else 
  begin
    m_axi_arvalid_reg <= m_axi_arvalid_next;
  end 
end

always @(*)
begin
  m_axi_arvalid_next = m_axi_arvalid_reg;
  if(Mout_oe_ram && !Mout_back_pressure_reg)
  begin
    m_axi_arvalid_next = 1;
  end
  else if(m_axi_arready)
  begin
    m_axi_arvalid_next = 0;  
  end
end

assign m_axi_arvalid = m_axi_arvalid_reg;

reg [BITSIZE_m_axi_araddr-1:0] m_axi_araddr_reg, m_axi_araddr_next;
reg [BITSIZE_m_axi_arsize-1:0] m_axi_arsize_reg, m_axi_arsize_next;
reg [BITSIZE_m_axi_awid-1:0] m_axi_arid_reg, m_axi_arid_next;


always @(posedge clock 1RESET_EDGE)
begin
  if(1RESET_VALUE)
  begin
    m_axi_araddr_reg <= 0;
    m_axi_arid_reg <= 0;
    m_axi_arsize_reg <= 0;
  end
  else
  begin
    m_axi_araddr_reg <= m_axi_araddr_next;
    m_axi_arid_reg <= m_axi_arid_next;
    m_axi_arsize_reg <= m_axi_arsize_next;
  end
end

always @(*)
begin
  m_axi_araddr_next = m_axi_araddr_reg;
  m_axi_arid_next = m_axi_arid_reg;
  m_axi_arsize_next = m_axi_arsize_reg;
  if(Mout_oe_ram && (!m_axi_arvalid_reg || m_axi_arready))
  begin
    m_axi_araddr_next = Mout_addr_ram;
    m_axi_arid_next = Mout_tag;
    m_axi_arsize_next = size_next;
  end
end

assign m_axi_araddr = m_axi_araddr_reg;
assign m_axi_arid = m_axi_arid_reg;
assign m_axi_arsize = m_axi_arsize_reg;

reg M_DataRdy_reg;

always @(posedge clock 1RESET_EDGE)
begin
  if(1RESET_VALUE)
  begin
    M_DataRdy_reg <= 0;
  end
  else
  begin
    M_DataRdy_reg <= M_back_pressure || double_answer_first_next || double_answer_second_next;
  end
end

assign M_DataRdy = (m_axi_bvalid && m_axi_bready) || (m_axi_rvalid && m_axi_rready) || M_DataRdy_reg;

reg [BITSIZE_M_Rdata_ram-1:0] M_Rdata_ram_reg;

always @(posedge clock 1RESET_EDGE)
begin
  if(1RESET_VALUE)
  begin
    M_Rdata_ram_reg <= 0;
  end
  else 
  begin
    M_Rdata_ram_reg <= M_Rdata_ram;
  end
end


assign M_Rdata_ram = m_axi_rvalid & m_axi_rready ? m_axi_rdata : M_Rdata_ram_reg;

reg m_axi_bready_reg;
reg m_axi_rready_reg;

always @(posedge clock 1RESET_EDGE)
begin
  if(1RESET_VALUE)
  begin
    m_axi_rready_reg <= 0;
    m_axi_bready_reg <= 0;
  end
  else if(M_back_pressure)
  begin
    m_axi_rready_reg <= 0;
    m_axi_bready_reg <= 0;
  end
  else if(double_answer_first_next || double_answer_second_next)
  begin
    m_axi_bready_reg <= 0;
    m_axi_rready_reg <= 0;
  end
  else
  begin
    m_axi_rready_reg <= 1;
    m_axi_bready_reg <= 1;
  end
end

assign m_axi_bready = m_axi_bready_reg;
assign m_axi_rready = m_axi_rready_reg;

reg [BITSIZE_M_tag-1:0] M_tag_reg, M_tag_next;

always @(posedge clock 1RESET_EDGE)
begin
  if(1RESET_VALUE)
  begin
    M_tag_reg <= 0;
    double_answer_first <= 0;
    double_answer_second <= 0;
  end
  else
  begin
    M_tag_reg <= M_tag_next;
    double_answer_first <= double_answer_first_next; 
    double_answer_second <= double_answer_second_next;   
  end
end

assign double_answer_first_next = (M_back_pressure && (m_axi_rready && m_axi_rvalid && m_axi_bready && m_axi_bvalid)) || (M_back_pressure && double_answer_first);
assign double_answer_second_next = (m_axi_rready && m_axi_rvalid && m_axi_bready && m_axi_bvalid) || (!double_answer_first_next && double_answer_first) || (M_back_pressure && double_answer_second);

always @(*)
begin
  if(M_back_pressure_old)
  begin
    M_tag_next = M_tag_reg;
  end
  else if(double_answer_first)
  begin
    M_tag_next = m_axi_rid_reg;
  end
  else if(double_answer_second)
  begin
    M_tag_next = m_axi_bid_reg;
  end
  else if(m_axi_rvalid && m_axi_rready)
  begin
    M_tag_next = m_axi_rid;
  end
  else if(m_axi_bvalid && m_axi_bready)
  begin
    M_tag_next = m_axi_bid;
  end
  else
  begin
    M_tag_next = 0;
  end
end

assign M_tag = M_tag_next;

// synthesis translate_off
always @(posedge clock)
begin
  if(m_axi_bresp != 0 || m_axi_rresp !=0)
  begin
    $display("ERROR: Sim: Abort incorret AXI answer from slave ");
    $finish;
  end
end
// synthesis translate_on

localparam integer FIFO_PTR_W = (FIFO_DEPTH <= 2) ? 1 : $clog2(FIFO_DEPTH);
localparam integer FIFO_COUNT_W = (FIFO_DEPTH <= 1) ? 1 : $clog2(FIFO_DEPTH + 1);
localparam integer DESC_PTR_W = (MAX_OUTSTANDING <= 2) ? 1 : $clog2(MAX_OUTSTANDING);
localparam integer DESC_COUNT_W = (MAX_OUTSTANDING <= 1) ? 1 : $clog2(MAX_OUTSTANDING + 1);
localparam integer RESERVATION_COUNT_W = (MAX_OUTSTANDING <= 1) ? 2 : $clog2(MAX_OUTSTANDING + 2);

// Widths come from the port parameters, so the same component serves any
// address and data width the interface asks for. vector_size in the XML is
// only the default of these parameters; the writer overrides them per
// instance.
localparam integer ADDR_BITS  = BITSIZE_m_axi_araddr;
localparam integer DATA_BITS  = BITSIZE_m_axi_rdata;
localparam integer BEAT_BYTES = DATA_BITS / 8;
localparam integer BEAT_SHIFT = $clog2(BEAT_BYTES);
// One bus beat carries one element, so ARSIZE is the beat size itself.
localparam integer ARSIZE_ENC = BEAT_SHIFT;
// Beat index domain: the top BEAT_SHIFT address bits carry no beat info.
localparam integer BEAT_IDX_BITS = ADDR_BITS - BEAT_SHIFT;
// Comparison domain for the last-beat check: it must also hold the element
// count, which is added to the beat index.
localparam integer COUNT_BITS = BITSIZE_in5;
localparam integer END_BEAT_W = (COUNT_BITS > BEAT_IDX_BITS ? COUNT_BITS : BEAT_IDX_BITS) + 1;
// AXI forbids a burst crossing a 4 KiB boundary.
localparam integer BOUNDARY_BEATS = 4096 / BEAT_BYTES;
localparam integer BOUNDARY_W = $clog2(BOUNDARY_BEATS) + 1;
// Element-count domain: validation proves a region holds at most 2^30
// elements, so the counters are one bit narrower than the count operand.
localparam integer COUNT_W = BITSIZE_in5 - 1;
// Burst-length domain: it must be able to hold B_MAX itself.
localparam integer LEN_W = $clog2(B_MAX + 1);
// ABI opcodes carried by in1.
localparam integer OP_LOAD = 0;
localparam integer OP_STORE = 1;
localparam integer OP_CONFIGURE = 2;

reg done_reg;
reg [BITSIZE_out1-1:0] out1_reg;
reg [ADDR_BITS-1:0] m_axi_araddr_reg;
reg [BITSIZE_m_axi_arlen-1:0] m_axi_arlen_reg;
reg m_axi_arvalid_reg;
reg fault_reg;
wire reset_n = !(1RESET_VALUE);

assign done = done_reg;
assign out1 = out1_reg;
assign fault = fault_reg;
assign m_axi_araddr = m_axi_araddr_reg;
assign m_axi_arlen = m_axi_arlen_reg;
assign m_axi_arvalid = m_axi_arvalid_reg;


reg        region_active;
reg [ADDR_BITS-1:0] region_base;
// Configuration validation proves count <= 2^30 before this narrowing.
// The element-count domain is 31 bits regardless of the address width: one
// region holds at most 2^30 elements.
reg [COUNT_W-1:0] region_count;
reg [ADDR_BITS-1:0] next_expected_address;
reg [COUNT_W-1:0] issued;
reg [COUNT_W-1:0] returned;
reg [COUNT_W-1:0] consumed;

reg        cfg_seen;
reg        cfg_pending;
// The descriptor of the configure request that cfg_seen is guarding. Holding start
// with the same operands is one request and must be captured once; holding start
// with different operands after the first request completed is a new request.
reg [BITSIZE_in2-1:0] cfg_size;
reg [ADDR_BITS-1:0] cfg_base;
// Full width on purpose: a count whose top bit is set is an invalid request, and a
// truncated copy would compare equal to the valid one it replaces, so the invalid
// request would never reach validation and would be silently dropped.
reg [COUNT_BITS-1:0] cfg_count;
reg [ADDR_BITS-1:0] pending_base;
reg [COUNT_W-1:0] pending_count;

reg        load_pending;
reg        load_pending_valid;
reg [ADDR_BITS-1:0] pending_load_address;
reg [BITSIZE_in2-1:0] pending_load_size_bits;
reg [DATA_BITS-1:0] fifo [0:FIFO_DEPTH-1];
reg [FIFO_PTR_W-1:0] fifo_rd_ptr;
reg [FIFO_PTR_W-1:0] fifo_wr_ptr;
reg [FIFO_COUNT_W-1:0] fifo_count;
reg [LEN_W-1:0] descriptor_remaining [0:MAX_OUTSTANDING-1];
reg [DESC_PTR_W-1:0] descriptor_rd_ptr;
reg [DESC_PTR_W-1:0] descriptor_wr_ptr;
reg [DESC_COUNT_W-1:0] descriptor_count;
wire burst_outstanding;
assign burst_outstanding = (descriptor_count != 0);
wire descriptor_pop;
wire descriptor_push;
reg        fifo_load_done;
wire       fifo_load_pop;
reg        load_request_valid;
wire       r_push;
wire       r_good;
wire       drain_complete;
reg        configure_complete;
reg        configure_descriptor_valid;
reg        configure_direct_capture;
wire       activate_pending;

reg [END_BEAT_W-1:0] end_beat_ext;
reg [COUNT_W-1:0] remaining_beats;
reg [ADDR_BITS-1:0] next_address;
reg [BOUNDARY_W-1:0] boundary_beats;
reg [FIFO_COUNT_W-1:0] credit_beats;
reg [LEN_W-1:0] next_burst_length;
reg [RESERVATION_COUNT_W-1:0] outstanding_after_reservation;
integer      fifo_credit;
wire         reservation_eligible;
// Highest legal beat index: one past the last beat of the address space.
wire [END_BEAT_W-1:0] end_beat_limit = {1'b1, {BEAT_IDX_BITS{1'b0}}};

// synthesis translate_off
initial begin
    if (!(B_MAX >= 1 && B_MAX <= 256))
        $fatal(1, "B_MAX must be in [1,256]");
    if (!(MAX_OUTSTANDING >= 1 && MAX_OUTSTANDING <= 16))
        $fatal(1, "MAX_OUTSTANDING must be in [1,16]");
    if (!(FIFO_DEPTH >= 1 && FIFO_DEPTH <= 4096 &&
          (FIFO_DEPTH & (FIFO_DEPTH - 1)) == 0))
        $fatal(1, "FIFO_DEPTH must be a power of two in [1,4096]");
    if (!(DATA_BITS >= 8 && DATA_BITS <= 4096 &&
          (DATA_BITS & (DATA_BITS - 1)) == 0))
        $fatal(1, "BITSIZE_m_axi_rdata must be a power-of-two width in [8,4096]");
    if (ADDR_BITS < 12)
        $fatal(1, "BITSIZE_m_axi_araddr must be at least 12 bits for the 4 KiB rule");
end
// synthesis translate_on


assign m_axi_arsize  = ARSIZE_ENC; // log2(bytes per beat, from the data width
assign m_axi_arburst = 2'b01; // INCR
assign m_axi_arid    = 1'b0;

// A FIFO word completes a load immediately. When empty, one command is
// retained until a word arrives, independently of the later start level.
always @* begin
    done_reg = 1'b0;
    out1_reg = {BITSIZE_out1{1'b0}};
    fifo_load_done = 1'b0;
    configure_complete = 1'b0;
    load_request_valid = region_active && consumed < region_count &&
                         in2 == DATA_BITS &&
                         in4 == next_expected_address;
    configure_descriptor_valid = in2 == DATA_BITS &&
                                 in4[BEAT_SHIFT-1:0] == {BEAT_SHIFT{1'b0}} &&
                                 // The region counters are COUNT_W bits wide, one narrower
                                 // than the count operand: a count with its top bit set
                                 // would truncate silently, and 0x80000000 becomes zero.
                                 in5[COUNT_BITS-1] == 1'b0 &&
                                 (in5 == 0 ||
                                  end_beat_ext <= end_beat_limit);
    configure_direct_capture = start && in1 == OP_CONFIGURE && !cfg_seen &&
                               !cfg_pending && configure_descriptor_valid &&
                               (!region_active || drain_complete);

    if (!fault_reg) begin
        if (load_pending && load_pending_valid &&
            pending_load_size_bits == DATA_BITS &&
            pending_load_address == next_expected_address && fifo_count != 0) begin
            done_reg = 1'b1;
            out1_reg = fifo[fifo_rd_ptr];
            fifo_load_done = 1'b1;
        end else if (!load_pending && start && in1 == OP_LOAD &&
                     load_request_valid && fifo_count != 0) begin
            done_reg = 1'b1;
            out1_reg = fifo[fifo_rd_ptr];
            fifo_load_done = 1'b1;
        end

        configure_complete = activate_pending;
        if (configure_direct_capture)
            configure_complete = 1'b1;
        done_reg = done_reg || configure_complete;
    end
end

assign fifo_load_pop = fifo_load_done;
assign r_push = m_axi_rvalid && m_axi_rready;
assign r_good = r_push && (m_axi_rid == 1'b0) && (m_axi_rresp == 2'b00) &&
    (((descriptor_count != 0) && descriptor_remaining[descriptor_rd_ptr] == 1 && m_axi_rlast) ||
     ((descriptor_count != 0) && descriptor_remaining[descriptor_rd_ptr] > 1 && !m_axi_rlast));
assign m_axi_rready = (descriptor_count != 0) && !fault_reg &&
                      ((fifo_count < FIFO_DEPTH) || fifo_load_pop);
assign descriptor_pop = r_push &&
    (descriptor_remaining[descriptor_rd_ptr] == 1) && m_axi_rlast &&
    (m_axi_rid == 1'b0) && (m_axi_rresp == 2'b00);
assign descriptor_push = m_axi_arvalid_reg && m_axi_arready;

always @* begin
    end_beat_ext = (in4 >> BEAT_SHIFT) + in5;

    remaining_beats = {COUNT_W{1'b0}};
    next_address = {ADDR_BITS{1'b0}};
    boundary_beats = {BOUNDARY_W{1'b0}};
    credit_beats = {FIFO_COUNT_W{1'b0}};
    next_burst_length = 0;
    outstanding_after_reservation =
        {{(RESERVATION_COUNT_W-DESC_COUNT_W){1'b0}}, descriptor_count} +
        {{(RESERVATION_COUNT_W-1){1'b0}}, m_axi_arvalid_reg};
    // issued >= consumed and issued-consumed <= FIFO_DEPTH: each
    // reservation is capped by free FIFO capacity, and consumption only
    // follows a received word. Keep this subtraction full-width so its
    // guard retains the original underflow/non-positive semantics; only
    // narrow the proven nonnegative capacity when selecting a burst.
    fifo_credit = FIFO_DEPTH - (issued - consumed);
    if (region_active && issued < region_count && !m_axi_arvalid_reg &&
        outstanding_after_reservation < MAX_OUTSTANDING && !fault_reg) begin
        remaining_beats = region_count - issued;
        // issued is strictly below a validated count <= 2^30, so the
        // shift cannot overflow the address domain.
        next_address = region_base + (issued << BEAT_SHIFT);
        boundary_beats = BOUNDARY_BEATS - next_address[11:BEAT_SHIFT];
        // issued-consumed includes every outstanding or buffered result.
        credit_beats = fifo_credit;
        next_burst_length = B_MAX;
        if (remaining_beats < next_burst_length)
            next_burst_length = remaining_beats;
        if (boundary_beats < next_burst_length)
            next_burst_length = boundary_beats;
        if (credit_beats < next_burst_length)
            next_burst_length = credit_beats;
    end
end

assign reservation_eligible = region_active && issued < region_count &&
    !m_axi_arvalid_reg && outstanding_after_reservation < MAX_OUTSTANDING &&
    fifo_credit > 0 && !fault_reg;

assign drain_complete = region_active &&
    issued == region_count && returned == region_count &&
    consumed == region_count && fifo_count == 0 &&
    !m_axi_arvalid && descriptor_count == 0 && !load_pending;
assign activate_pending = drain_complete && cfg_pending;

always @(posedge clock) begin
    if (!reset_n) begin
        region_active <= 1'b0;
        region_base <= {ADDR_BITS{1'b0}};
        region_count <= {COUNT_W{1'b0}};
        next_expected_address <= {ADDR_BITS{1'b0}};
        issued <= {COUNT_W{1'b0}};
        returned <= {COUNT_W{1'b0}};
        consumed <= {COUNT_W{1'b0}};
        cfg_seen <= 1'b0;
        cfg_pending <= 1'b0;
        cfg_size <= {BITSIZE_in2{1'b0}};
        cfg_base <= {ADDR_BITS{1'b0}};
        cfg_count <= {COUNT_BITS{1'b0}};
        pending_base <= {ADDR_BITS{1'b0}};
        pending_count <= {COUNT_W{1'b0}};
        load_pending <= 1'b0;
        load_pending_valid <= 1'b0;
        pending_load_address <= {ADDR_BITS{1'b0}};
        pending_load_size_bits <= {BITSIZE_in2{1'b0}};
        fifo_rd_ptr <= 0;
        fifo_wr_ptr <= 0;
        fifo_count <= 0;
        descriptor_rd_ptr <= 0;
        descriptor_wr_ptr <= 0;
        descriptor_count <= 0;
        m_axi_araddr_reg <= {ADDR_BITS{1'b0}};
        m_axi_arlen_reg <= {BITSIZE_m_axi_arlen{1'b0}};
        m_axi_arvalid_reg <= 1'b0;
        fault_reg <= 1'b0;
    end else begin
        if (!start || in1 != OP_CONFIGURE)
            cfg_seen <= 1'b0;
        else if (!cfg_pending &&
                 (in2 != cfg_size || in4 != cfg_base || in5 != cfg_count))
            // The guarded request is finished - it is no longer waiting to be
            // activated - and the operands now differ, so the caller is presenting a
            // new configure even though start never dropped. Every operand is compared
            // at full width: comparing only the address and a truncated count makes an
            // invalid request look like the one already guarded, so it never reaches
            // validation and produces neither done nor fault. Identical operands keep
            // the single-capture behaviour, and a request still pending activation
            // must not be replaced.
            cfg_seen <= 1'b0;

        // Capture a configure request exactly once while start is held.
        if (start && in1 == OP_CONFIGURE && !cfg_seen) begin
            cfg_seen <= 1'b1;
            cfg_size <= in2;
            cfg_base <= in4;
            cfg_count <= in5;
            if (!configure_descriptor_valid) begin
                fault_reg <= 1'b1;
            end else if (!region_active && !cfg_pending) begin
                region_active <= 1'b1;
                region_base <= in4;
                region_count <= in5[COUNT_W-1:0];
                next_expected_address <= in4;
                issued <= {COUNT_W{1'b0}};
                returned <= {COUNT_W{1'b0}};
                consumed <= {COUNT_W{1'b0}};
                fifo_rd_ptr <= 0;
                fifo_wr_ptr <= 0;
                fifo_count <= 0;
                load_pending <= 1'b0;
                load_pending_valid <= 1'b0;
            end else if (drain_complete && !cfg_pending) begin
                // Capture the replacement directly if the old region is
                // already drained on this edge; do not clear active below.
                region_active <= 1'b1;
                region_base <= in4;
                region_count <= in5[COUNT_W-1:0];
                next_expected_address <= in4;
                issued <= {COUNT_W{1'b0}};
                returned <= {COUNT_W{1'b0}};
                consumed <= {COUNT_W{1'b0}};
                fifo_rd_ptr <= 0;
                fifo_wr_ptr <= 0;
                fifo_count <= 0;
                load_pending <= 1'b0;
                load_pending_valid <= 1'b0;
            end else if (!cfg_pending) begin
                cfg_pending <= 1'b1;
                pending_base <= in4;
                pending_count <= in5[COUNT_W-1:0];
            end else begin
                fault_reg <= 1'b1;
            end
        end

        // Record one load command when the response FIFO is empty.
        if (start && in1 == OP_LOAD && !load_pending) begin
            if (!load_request_valid)
                fault_reg <= 1'b1;
            else if (fifo_count == 0) begin
                load_pending <= 1'b1;
                load_pending_valid <= load_request_valid;
                pending_load_address <= in4;
                pending_load_size_bits <= in2;
            end
        end
        if (fifo_load_done) begin
            load_pending <= 1'b0;
            load_pending_valid <= 1'b0;
            consumed <= consumed + 1'b1;
            if (fifo_rd_ptr == FIFO_DEPTH-1)
                fifo_rd_ptr <= 0;
            else
                fifo_rd_ptr <= fifo_rd_ptr + 1'b1;
            if (consumed + 1'b1 < region_count)
                next_expected_address <= next_expected_address + BEAT_BYTES;
        end

        // Reserve and freeze one descriptor before asserting ARVALID.
        if (reservation_eligible) begin
            m_axi_araddr_reg <= next_address;
            // 9 bits are required to represent length 256; subtract in
            // that domain, then retain the 8-bit AXI ARLEN encoding.
            m_axi_arlen_reg <= next_burst_length - 1'b1;
            m_axi_arvalid_reg <= 1'b1;
        end

        if (m_axi_arvalid_reg && m_axi_arready) begin
            m_axi_arvalid_reg <= 1'b0;
            descriptor_remaining[descriptor_wr_ptr] <= {1'b0, m_axi_arlen_reg} + 1'b1;
            if (descriptor_wr_ptr == MAX_OUTSTANDING-1)
                descriptor_wr_ptr <= 0;
            else
                descriptor_wr_ptr <= descriptor_wr_ptr + 1'b1;
            issued <= issued + {{(COUNT_W-BITSIZE_m_axi_arlen){1'b0}}, m_axi_arlen_reg} + 1'b1;
        end

        case ({descriptor_push, descriptor_pop})
            2'b10: descriptor_count <= descriptor_count + 1'b1;
            2'b01: descriptor_count <= descriptor_count - 1'b1;
            default: descriptor_count <= descriptor_count;
        endcase

            if (r_push) begin
            if (m_axi_rid != 1'b0 || m_axi_rresp != 2'b00 ||
                (descriptor_count == 0) ||
                (descriptor_remaining[descriptor_rd_ptr] == 1 && !m_axi_rlast) ||
                (descriptor_remaining[descriptor_rd_ptr] > 1 && m_axi_rlast))
                fault_reg <= 1'b1;
            if (r_good) begin
                returned <= returned + 1'b1;
                fifo[fifo_wr_ptr] <= m_axi_rdata;
                if (fifo_wr_ptr == FIFO_DEPTH-1)
                    fifo_wr_ptr <= 0;
                else
                    fifo_wr_ptr <= fifo_wr_ptr + 1'b1;
                if (descriptor_remaining[descriptor_rd_ptr] == 1) begin
                    if (descriptor_rd_ptr == MAX_OUTSTANDING-1)
                        descriptor_rd_ptr <= 0;
                    else
                        descriptor_rd_ptr <= descriptor_rd_ptr + 1'b1;
                end else begin
                    descriptor_remaining[descriptor_rd_ptr] <=
                        descriptor_remaining[descriptor_rd_ptr] - 1'b1;
                end
            end
        end

        case ({r_good, fifo_load_pop})
            2'b10: fifo_count <= fifo_count + 1'b1;
            2'b01: fifo_count <= fifo_count - 1'b1;
            default: fifo_count <= fifo_count;
        endcase

        if (activate_pending) begin
            region_active <= 1'b1;
            region_base <= pending_base;
            region_count <= pending_count;
            next_expected_address <= pending_base;
            issued <= {COUNT_W{1'b0}};
            returned <= {COUNT_W{1'b0}};
            consumed <= {COUNT_W{1'b0}};
            fifo_rd_ptr <= 0;
            fifo_wr_ptr <= 0;
            fifo_count <= 0;
            descriptor_rd_ptr <= 0;
            descriptor_wr_ptr <= 0;
            descriptor_count <= 0;
            cfg_pending <= 1'b0;
            load_pending <= 1'b0;
            load_pending_valid <= 1'b0;
        end else if (drain_complete && !configure_direct_capture) begin
            region_active <= 1'b0;
        end

        // Keep a sticky error, including unsupported stores. A fault_reg
        // suppresses the done handshake and is observable on the fault output.
        if (start && in1 == OP_STORE)
            fault_reg <= 1'b1;
    end
end

assign m_axi_arlen = 0;
assign m_axi_arburst = BURST_TYPE;
assign m_axi_arlock = 0;
assign m_axi_arcache = 0;
assign m_axi_arprot = 0;
assign m_axi_arqos = 0;
assign m_axi_arregion = 0;
assign m_axi_aruser = 0;
assign m_axi_arid = 0;
assign m_axi_awlen = 0;
assign m_axi_awburst = BURST_TYPE;
assign m_axi_awlock = 0;
assign m_axi_awcache = 0;
assign m_axi_awprot = 0;
assign m_axi_awqos = 0;
assign m_axi_awregion = 0;
assign m_axi_awuser = 0;
assign m_axi_awid = 0;
assign m_axi_wlast = 1;
assign m_axi_wuser = 0;

`ifndef _SIM_HAVE_CLOG2
  function integer log2;
     input integer value;
     integer temp_value;
    begin
      temp_value = value-1;
      for (log2=0; temp_value>0; log2=log2+1)
        temp_value = temp_value>>1;
    end
  endfunction
`endif

wire [2:0] size_next;

generate
  `ifdef _SIM_HAVE_CLOG2
    assign size_next = $clog2(Mout_data_ram_size >> 3);
  `else
    assign size_next = `log2(Mout_data_ram_size >> 3);
  `endif
endgenerate

reg double_answer_second;
wire double_answer_second_next;

reg m_axi_awvalid_reg, m_axi_awvalid_next;
reg m_axi_wvalid_reg, m_axi_wvalid_next;
reg m_axi_arvalid_reg, m_axi_arvalid_next;

always @(posedge clock 1RESET_EDGE)
begin
  if(1RESET_VALUE)
  begin
    m_axi_awvalid_reg <= 0;
    m_axi_wvalid_reg <= 0;
  end
  else 
  begin
    m_axi_awvalid_reg <= m_axi_awvalid_next;
    m_axi_wvalid_reg <= m_axi_wvalid_next;
  end 
end

always @(*)
begin
  m_axi_awvalid_next = m_axi_awvalid_reg;
  m_axi_wvalid_next = m_axi_wvalid_reg;
  if(Mout_we_ram)
  begin
    m_axi_awvalid_next = 1;
    m_axi_wvalid_next = 1;
  end
  else
  begin
    if(m_axi_awready)
    begin
      m_axi_awvalid_next = 0;  
    end
    if(m_axi_wready)
    begin
      m_axi_wvalid_next = 0;  
    end
  end
end

assign m_axi_wvalid = m_axi_wvalid_reg;
assign m_axi_awvalid = m_axi_awvalid_reg;

reg [BITSIZE_Mout_Wdata_ram-1:0] m_axi_wdata_reg;
reg [BITSIZE_m_axi_wstrb-1:0] m_axi_wstrb_reg;

always @(posedge clock 1RESET_EDGE)
begin
  if(1RESET_VALUE)
  begin
    m_axi_wdata_reg <= 0;
    m_axi_wstrb_reg <= 0;
  end
  else
  begin
    m_axi_wdata_reg <= Mout_Wdata_ram;
    m_axi_wstrb_reg <= ((1 << (Mout_data_ram_size >> 3)) - 1);
  end
end

assign m_axi_wdata = m_axi_wdata_reg; 
assign m_axi_wstrb = m_axi_wstrb_reg;

reg [BITSIZE_m_axi_awaddr-1:0] m_axi_awaddr_reg;
reg [BITSIZE_m_axi_awsize-1:0] m_axi_awsize_reg;

always @(posedge clock 1RESET_EDGE)
begin
  if(1RESET_VALUE)
  begin
    m_axi_awaddr_reg <= 0;
    m_axi_awsize_reg <= 0;
  end
  else
  begin
    m_axi_awaddr_reg <= Mout_addr_ram;
    m_axi_awsize_reg <= size_next;
  end
end

assign m_axi_awsize = m_axi_awsize_reg;
assign m_axi_awaddr = m_axi_awaddr_reg;

always @(posedge clock 1RESET_EDGE)
begin
  if(1RESET_VALUE)
  begin
    m_axi_arvalid_reg <= 0;
  end
  else 
  begin
    m_axi_arvalid_reg <= m_axi_arvalid_next;
  end 
end

always @(*)
begin
  m_axi_arvalid_next = m_axi_arvalid_reg;
  if(Mout_oe_ram)
  begin
    m_axi_arvalid_next = 1;
  end
  else if(m_axi_arready)
  begin
    m_axi_arvalid_next = 0;  
  end
end

assign m_axi_arvalid = m_axi_arvalid_reg;

reg [BITSIZE_m_axi_araddr-1:0] m_axi_araddr_reg;
reg [BITSIZE_m_axi_arsize-1:0] m_axi_arsize_reg;

always @(posedge clock 1RESET_EDGE)
begin
  if(1RESET_VALUE)
  begin
    m_axi_araddr_reg <= 0;
    m_axi_arsize_reg <= 0;
  end
  else
  begin
    m_axi_araddr_reg <= Mout_addr_ram;
    m_axi_arsize_reg <= size_next;
  end
end

assign m_axi_arsize = m_axi_arsize_reg;
assign m_axi_araddr = m_axi_araddr_reg;

reg M_DataRdy_reg;

always @(posedge clock 1RESET_EDGE)
begin
  if(1RESET_VALUE)
  begin
    M_DataRdy_reg <= 0;
  end
  else
  begin
    M_DataRdy_reg <= double_answer_second_next;
  end
end

assign M_DataRdy = (m_axi_bvalid && m_axi_bready) || (m_axi_rvalid && m_axi_rready) || M_DataRdy_reg;
assign M_Rdata_ram = m_axi_rdata;

reg m_axi_bready_reg;
reg m_axi_rready_reg;

always @(posedge clock 1RESET_EDGE)
begin
  if(1RESET_VALUE)
  begin
    m_axi_rready_reg <= 0;
    m_axi_bready_reg <= 0;
  end
  else if(double_answer_second_next)
  begin
    m_axi_bready_reg <= 0;
    m_axi_rready_reg <= 0;
  end
  else
  begin
    m_axi_rready_reg <= 1;
    m_axi_bready_reg <= 1;
  end
end

assign m_axi_bready = m_axi_bready_reg;
assign m_axi_rready = m_axi_rready_reg;

always @(posedge clock 1RESET_EDGE)
begin
  if(1RESET_VALUE)
  begin
    double_answer_second <= 0;
  end
  else
  begin
    double_answer_second <= double_answer_second_next;   
  end
end

assign double_answer_second_next = (m_axi_rready && m_axi_rvalid && m_axi_bready && m_axi_bvalid);

// synthesis translate_off
always @(posedge clock)
begin
  if(m_axi_bresp != 0 || m_axi_rresp !=0)
  begin
    $display("ERROR: Sim: Abort incorret AXI answer from slave ");
    $finish;
  end
end
// synthesis translate_on
